args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?director ?directorLabel ?minBirth WHERE {
  VALUES ?film { dbr:The_Marriage_of_Princess_Demidoff dbr:The_Pocket-knife }

  {
    SELECT ?film (MIN(?bdate) AS ?minBirth) WHERE {
      VALUES ?film { dbr:The_Marriage_of_Princess_Demidoff dbr:The_Pocket-knife }
      {
        ?film dbo:director ?d .
      } UNION {
        ?film dbp:director ?d .
      }
      ?d dbo:birthDate ?bdate .
    } GROUP BY ?film
  }

  # find director(s) having that minimum birth date for the film
  {
    ?film dbo:director ?director .
  } UNION {
    ?film dbp:director ?director .
  }
  ?director dbo:birthDate ?minBirth .

  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(lang(?filmLabel) = "en") }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(lang(?directorLabel) = "en") }
}
ORDER BY ?minBirth
LIMIT 1

